export type ReactCostStamp = {
  name: string;
  start: number;
  end: number;
  track: string | null;
  group: string | null;
  color: string | null;
  observedAt: number;
};
export type ReactCostRoot = {
  id: string;
  phase: string;
  actualDuration: number;
  baseDuration: number;
  startTime: number;
  commitTime: number;
};
export type ReactCostStats = {
  startedAt: number;
  stoppedAt: number;
  stamps: ReactCostStamp[];
  roots: ReactCostRoot[];
  nonNumericReactStamps: number;
  errors: string[];
  restoredTimeStamp: boolean;
};
export type ReactCostApi = {
  begin: () => ReactCostStats;
  stop: () => ReactCostStats;
  recordRoot: (args: unknown[]) => void;
};
type CostWindow = Window & { __kandevReactCost: ReactCostApi };

function emptyStats(): ReactCostStats {
  return {
    startedAt: 0,
    stoppedAt: 0,
    stamps: [],
    roots: [],
    nonNumericReactStamps: 0,
    errors: [],
    restoredTimeStamp: false,
  };
}
function installReactCostObserver() {
  const win = window as unknown as CostWindow;
  const original = console.timeStamp;
  if (typeof original !== "function") throw Error("React cost observer requires console.timeStamp");
  let active = false;
  let stats = emptyStats();
  const wrapper = (...args: unknown[]) => {
    if (active && (args[3] === "Components ⚛" || args[4] === "Scheduler ⚛")) {
      if (
        typeof args[1] === "number" &&
        typeof args[2] === "number" &&
        Number.isFinite(args[1]) &&
        Number.isFinite(args[2])
      ) {
        stats.stamps.push({
          name: String(args[0]),
          start: args[1],
          end: args[2],
          track: typeof args[3] === "string" ? args[3] : null,
          group: typeof args[4] === "string" ? args[4] : null,
          color: typeof args[5] === "string" ? args[5] : null,
          observedAt: performance.now(),
        });
      } else stats.nonNumericReactStamps++;
    }
    return (original as (...values: unknown[]) => void).apply(console, args);
  };
  win.__kandevReactCost = {
    begin() {
      if (active) throw Error("React cost observer is already active");
      stats = emptyStats();
      stats.startedAt = performance.now();
      console.timeStamp = wrapper;
      active = true;
      return structuredClone(stats);
    },
    stop() {
      active = false;
      stats.stoppedAt = performance.now();
      if (console.timeStamp === wrapper) {
        console.timeStamp = original;
        stats.restoredTimeStamp = true;
      }
      return structuredClone(stats);
    },
    recordRoot(args) {
      if (!active) return;
      const [id, phase, actualDuration, baseDuration, startTime, commitTime] = args;
      if (
        typeof id !== "string" ||
        typeof phase !== "string" ||
        ![actualDuration, baseDuration, startTime, commitTime].every(
          (value) => typeof value === "number" && Number.isFinite(value),
        )
      ) {
        if (stats.errors.length < 10) stats.errors.push("Invalid root Profiler callback arguments");
        return;
      }
      stats.roots.push({
        id,
        phase,
        actualDuration: actualDuration as number,
        baseDuration: baseDuration as number,
        startTime: startTime as number,
        commitTime: commitTime as number,
      });
    },
  };
}
installReactCostObserver();

import { createElement, Profiler, useLayoutEffect, useEffect, useState } from "react";
import { createRoot } from "react-dom/client";
import type { ReactCostApi } from "./react-cost-observer";

const counts = { renders: 0, layout: 0, passive: 0, completedTick: -1 };
let setTick: (value: number) => void = () => {};
const originalTimeStamp = console.timeStamp;
function calibrationWork(milliseconds: number) {
  const until = performance.now() + milliseconds;
  while (performance.now() < until) {
    // Intentional CPU stimulus for the private profiler calibration.
  }
}
function CalibrationWork() {
  const [tick, update] = useState(0);
  setTick = update;
  calibrationWork(2);
  counts.renders++;
  useLayoutEffect(() => {
    calibrationWork(3);
    counts.layout++;
  }, [tick]);
  useEffect(() => {
    calibrationWork(5);
    counts.passive++;
    counts.completedTick = tick;
  }, [tick]);
  return createElement("span", { id: "calibration-tick" }, String(tick));
}
const win = window as unknown as Window & {
  __kandevReactCost: ReactCostApi;
  __reactCostCalibration: {
    counts: typeof counts;
    setTick: (value: number) => void;
    originalTimeStamp: typeof console.timeStamp;
  };
};
win.__reactCostCalibration = { counts, setTick: (value) => setTick(value), originalTimeStamp };
createRoot(document.getElementById("root")!).render(
  createElement(
    Profiler,
    { id: "cost-calibration", onRender: (...args) => win.__kandevReactCost.recordRoot(args) },
    createElement(CalibrationWork),
  ),
);

import fs from "node:fs";
import path from "node:path";
import type { Browser, Page } from "@playwright/test";
import type { StoreApi } from "zustand";
import type { AppState } from "@/lib/state/app-state-types";
import { test, expect } from "../../fixtures/test-base";
import { prepareDenseComparisonFixture } from "../../helpers/dense-comparison-fixture";
import { prepareDenseStream } from "../../helpers/dense-canonical-stream";
import { verifyDenseThreadsFiles } from "../../helpers/dense-threads-fixture";
import { loadDenseCold } from "../../helpers/dense-cold-load";
import { captureDenseTraffic } from "../../helpers/dense-measurement";
import { dwell } from "../../helpers/causal-waits";
import { sha256File } from "../../helpers/dense-snapshot";
import type { ReactCostApi, ReactCostStats } from "./react-cost-observer";

type ProbeWindow = Window & { __kandevReactCost: ReactCostApi };
type CalibrationWindow = ProbeWindow & {
  __reactCostCalibration: {
    counts: { renders: number; layout: number; passive: number; completedTick: number };
    setTick: (value: number) => void;
    originalTimeStamp: typeof console.timeStamp;
  };
};
const directory = path.resolve(
  process.cwd(),
  "../../.kandev/diagnostics/dense-workbench-performance",
);
const bundleDirectory = process.env.KANDEV_REACT_COST_BUNDLE_DIR!;
const observerBundle = path.join(bundleDirectory, "react-cost-observer.js");
const calibrationBundle = path.join(bundleDirectory, "react-cost-calibration.js");

async function calibrate(browser: Browser) {
  const context = await browser.newContext();
  const page = await context.newPage();
  try {
    await page.addInitScript({ path: observerBundle });
    await page.goto("data:text/html,<div id=root></div>");
    await page.addScriptTag({ path: calibrationBundle });
    await page.waitForFunction(
      () => (window as CalibrationWindow).__reactCostCalibration?.counts.completedTick === 0,
    );
    const before = await page.evaluate(() => {
      const win = window as CalibrationWindow;
      const counts = structuredClone(win.__reactCostCalibration.counts);
      win.__kandevReactCost.begin();
      return counts;
    });
    for (let tick = 1; tick <= 5; tick++) {
      await page.evaluate(
        (value) => (window as CalibrationWindow).__reactCostCalibration.setTick(value),
        tick,
      );
      await page.waitForFunction(
        (value) =>
          (window as CalibrationWindow).__reactCostCalibration.counts.completedTick === value,
        tick,
      );
    }
    return await page.evaluate((prior) => {
      const win = window as CalibrationWindow;
      const fixture = win.__reactCostCalibration;
      const probe = win.__kandevReactCost.stop();
      return {
        actual: {
          renders: fixture.counts.renders - prior.renders,
          layout: fixture.counts.layout - prior.layout,
          passive: fixture.counts.passive - prior.passive,
        },
        restoredTimeStamp: console.timeStamp === fixture.originalTimeStamp,
        probe,
      };
    }, before);
  } finally {
    await context.close();
  }
}

async function rendererEnvironment(browser: Browser) {
  const cdp = await browser.newBrowserCDPSession();
  try {
    const version = await cdp.send("Browser.getVersion");
    const system = await cdp.send("SystemInfo.getInfo");
    let renderingArguments: string[] | null = null;
    let commandLineError: string | null = null;
    try {
      const command = await cdp.send("Browser.getBrowserCommandLine");
      renderingArguments = command.arguments.filter((argument: string) =>
        /--(?:headless|use-gl|use-angle|disable-gpu|disable-software|in-process-gpu|ozone)/.test(
          argument,
        ),
      );
    } catch (error) {
      const detail = String(error);
      if (!detail.includes("Command line not returned because --enable-automation not set"))
        throw error;
      commandLineError = detail;
    }
    return { version, system, renderingArguments, commandLineError };
  } finally {
    await cdp.detach();
  }
}

async function loadedHistory(page: Page, sessionIds: string[]) {
  return page.evaluate((ids) => {
    const store = (window as unknown as { __KANDEV_E2E_STORE__: StoreApi<AppState> })
      .__KANDEV_E2E_STORE__;
    return ids.map((sessionId) => ({
      sessionId,
      messages: store.getState().messages.bySession[sessionId]?.length ?? 0,
    }));
  }, sessionIds);
}

test("captures React profiling phases and components during an ordered stream", async ({
  browser,
  testPage,
  apiClient: api,
  seedData: seed,
  backend,
}, info) => {
  test.setTimeout(600_000);
  fs.mkdirSync(directory, { recursive: true });
  const output = path.join(directory, `react-cost-${Date.now()}.json`);
  const report: Record<string, unknown> = {
    measurementKind: "react-cost-attribution",
    assetsSha256: process.env.KANDEV_REACT_COST_PROFILE_ASSETS,
    bundles: [observerBundle, calibrationBundle].map((file) => ({
      path: file,
      sha256: sha256File(file),
    })),
    limits:
      "Private production-mode React profiling build, readable code and root Profiler. React-provided component/effect spans are inclusive and can overlap. They must not be added as CPU totals. Calibration uses bounded artificial CPU work. This is cost attribution, not a production speed, INP, M2 Air, battery or heap-leak measurement.",
  };
  const checkpoint = () => {
    const temporary = output + ".pending";
    fs.writeFileSync(temporary, JSON.stringify(report, null, 2));
    const fd = fs.openSync(temporary, "r");
    fs.fsyncSync(fd);
    fs.closeSync(fd);
    fs.renameSync(temporary, output);
  };
  let stream: Awaited<ReturnType<typeof prepareDenseStream>> | undefined;
  let context: Awaited<ReturnType<Browser["newContext"]>> | undefined;
  let page: Page | undefined;
  let probeActive = false;
  try {
    const calibration = await calibrate(browser);
    report.calibration = calibration;
    checkpoint();
    expect(calibration.actual).toEqual({ renders: 5, layout: 5, passive: 5 });
    expect(calibration.probe.errors).toEqual([]);
    expect(calibration.restoredTimeStamp).toBe(true);
    expect(calibration.probe.restoredTimeStamp).toBe(true);
    expect(calibration.probe.roots).toHaveLength(5);
    expect(
      calibration.probe.roots.every(
        (root) =>
          root.id === "cost-calibration" && root.phase === "update" && root.actualDuration >= 1.5,
      ),
    ).toBe(true);
    const component = calibration.probe.stamps.filter(
      (stamp) => stamp.name.startsWith("CalibrationWork") && stamp.track === "Components ⚛",
    );
    expect(
      component.some(
        (stamp) => stamp.color?.startsWith("primary") && stamp.end - stamp.start >= 1.5,
      ),
    ).toBe(true);
    expect(
      component.some(
        (stamp) => stamp.color?.startsWith("secondary") && stamp.end - stamp.start >= 2.5,
      ),
    ).toBe(true);
    for (const name of ["Render", "Commit", "Remaining Effects"])
      expect(
        calibration.probe.stamps.some(
          (stamp) => stamp.name === name && stamp.group === "Scheduler ⚛",
        ),
      ).toBe(true);
    report.rendererEnvironment = await rendererEnvironment(browser);
    const prepared = await prepareDenseComparisonFixture(api, seed, backend, testPage);
    report.fixture = prepared.fixture;
    report.fixtureReplay = prepared.provenance;
    checkpoint();
    const database = path.join(backend.tmpDir, "react-cost.db");
    fs.copyFileSync(prepared.snapshot, database);
    expect(sha256File(database)).toBe(prepared.provenance?.databaseSha256);
    await backend.restart({
      KANDEV_DATABASE_PATH: database,
      KANDEV_HOME_DIR: path.join(backend.tmpDir, "react-cost-home"),
      KANDEV_WEB_DIST_DIR: path.join(process.env.KANDEV_REACT_COST_PROFILE_ROOT!, "apps/web/dist"),
      KANDEV_LOG_LEVEL: "warn",
      ...prepared.restartEnv,
    });
    report.filesBefore = await verifyDenseThreadsFiles(api, prepared.backend, prepared.fixture);
    const threads = prepared.fixture.threads.slice(0, 6);
    stream = await prepareDenseStream(
      api,
      prepared.seed,
      prepared.backend,
      threads,
      prepared.sampleNamespace + "react-cost",
    );
    context = await browser.newContext({
      baseURL: backend.frontendUrl,
      viewport: { width: 1470, height: 956 },
      deviceScaleFactor: 2,
      locale: "en-US",
    });
    page = await context.newPage();
    await page.addInitScript({ path: observerBundle });
    await page.addInitScript((port) => {
      localStorage.setItem("kandev.onboarding.completed", "true");
      window.__KANDEV_API_PORT = port;
      (window as unknown as { __KANDEV_E2E_EXPOSE_STORE__: boolean }).__KANDEV_E2E_EXPOSE_STORE__ =
        true;
    }, String(backend.port));
    report.cold = await loadDenseCold({
      page,
      workspaceId: prepared.seed.workspaceId,
      threads,
      warmup: stream.warmup,
      traffic: captureDenseTraffic(page),
    });
    const sessionIds = threads.map((thread) => thread.sessionId);
    report.initialLoadedHistory = await loadedHistory(page, sessionIds);
    expect(report.initialLoadedHistory).toEqual(
      sessionIds.map((sessionId) => ({ sessionId, messages: 100 })),
    );
    report.initialProbe = await page.evaluate(() =>
      (window as ProbeWindow).__kandevReactCost.begin(),
    );
    probeActive = true;
    stream.release();
    await dwell(
      page,
      prepared.fixture.workload.durationMs,
      "clock-separation",
      "capture React render, commit and effect costs in a private profiling build; excluded from speed evidence",
    );
    report.counts = await page.evaluate(() => (window as ProbeWindow).__kandevReactCost.stop());
    probeActive = false;
    checkpoint();
    const counts = report.counts as ReactCostStats;
    expect(counts.errors).toEqual([]);
    expect(counts.restoredTimeStamp).toBe(true);
    expect(counts.roots.length).toBeGreaterThan(0);
    expect(counts.roots.every((root) => root.id === "dense-private-cost")).toBe(true);
    expect(counts.stamps.some((stamp) => stamp.track === "Components ⚛")).toBe(true);
    expect(counts.stamps.some((stamp) => stamp.group === "Scheduler ⚛")).toBe(true);
    expect(counts.stoppedAt - counts.startedAt).toBeGreaterThanOrEqual(
      prepared.fixture.workload.durationMs,
    );
    await stream.waitForVisible(page);
    await stream.verify();
    report.scheduledUpdates = stream.scheduledUpdates;
    report.verificationErrors = stream.verificationErrors;
    report.allOrderedUpdatesVerified = true;
    report.finalLoadedHistory = await loadedHistory(page, sessionIds);
    expect(report.finalLoadedHistory).toEqual(report.initialLoadedHistory);
    report.filesAfter = await verifyDenseThreadsFiles(api, prepared.backend, prepared.fixture);
    expect(report.filesAfter).toEqual(report.filesBefore);
  } catch (error) {
    report.error = String(error);
    throw error;
  } finally {
    if (page && probeActive) {
      try {
        report.partialCounts = await page.evaluate(() =>
          (window as ProbeWindow).__kandevReactCost.stop(),
        );
      } catch (error) {
        report.stopError = String(error);
      }
    }
    try {
      await stream?.finish();
    } catch (error) {
      report.finishError = String(error);
    }
    try {
      await context?.close();
    } catch (error) {
      report.closeError = String(error);
    }
    checkpoint();
    await info.attach("react-cost-attribution", {
      path: output,
      contentType: "application/json",
    });
  }
});
